// שליחה מהווטסאפ העסקי מתוך הדשבורד: הדשבורד מכניס לתור (לשונית "תור וואטסאפ"), העוזרת במק מושכת כל 20 שנ' (api=outbox + ALERT_KEY), שולחת דרך הגשר ומעדכנת סטטוס
function outboxSheet_() { const ss = SpreadsheetApp.getActive(); let sh = ss.getSheetByName('תור וואטסאפ'); if (sh) return sh;
  sh = ss.insertSheet('תור וואטסאפ'); sh.appendRow(['מזהה', 'נוצר', 'טלפון', 'למי', 'הודעה', 'סטטוס', 'עודכן']); sh.setFrozenRows(1); sh.setRightToLeft(true); sh.getRange('C:C').setNumberFormat('@'); return sh; }
function stripEmoji_(s) { return String(s || '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}\u{20E3}]/gu, '').replace(/[ \t]{2,}/g, ' ').trim(); }
function dashboardWaSend(phone, text, label) { requireStaff(); let d = String(phone || '').replace(/[^0-9]/g, '');
  if (d.indexOf('0') === 0) d = '972' + d.slice(1); else if (d.length === 9) d = '972' + d;
  if (!/^972\d{8,9}$/.test(d)) throw new Error('מספר טלפון לא תקין: ' + phone);
  text = stripEmoji_(text).slice(0, 2000); if (!text) throw new Error('ההודעה ריקה');
  const id = Utilities.getUuid().slice(0, 8); outboxSheet_().appendRow([id, new Date(), d, String(label || '').slice(0, 60), text, 'ממתין', '']); return { id }; }
function dashboardWaStatus(ids) { requireStaff(); const sh = outboxSheet_(), n = sh.getLastRow(), out = {}; if (n < 2) return out; const from = Math.max(2, n - 80);
  sh.getRange(from, 1, n - from + 1, 6).getValues().forEach(r => { const id = String(r[0]); if (!ids || ids.indexOf(id) >= 0) out[id] = String(r[5]); }); return out; }
function outboxApi_(p) { const key = PropertiesService.getScriptProperties().getProperty('ALERT_KEY'); if (!key || String(p.k || '') !== key) throw new Error('אין הרשאה');
  const sh = outboxSheet_(), n = sh.getLastRow(); if (n < 2) return []; const rows = sh.getRange(2, 1, n - 1, 6).getValues();
  if (p.done) { for (let i = rows.length - 1; i >= 0; i--) if (String(rows[i][0]) === String(p.done)) { sh.getRange(i + 2, 6, 1, 2).setValues([[String(p.st || 'נשלח').slice(0, 100), new Date()]]); break; } return []; }
  const cut = Date.now() - 6 * 3600e3, out = [];
  rows.forEach((r, i) => { if (out.length < 10 && r[5] === 'ממתין' && r[1] instanceof Date && r[1].getTime() > cut) { out.push({ id: String(r[0]), phone: String(r[2]), label: String(r[3]), text: String(r[4]) }); sh.getRange(i + 2, 6).setValue('שולח'); } });
  return out; }
