function cached_(key, sec, fn) { const c = CacheService.getScriptCache(), h = c.get(key); if (h) { try { return JSON.parse(h); } catch (e) {} }
  const r = fn(); try { const s = JSON.stringify(r); if (s.length < 95000) c.put(key, s, sec); } catch (e) {} return r; }
