/* שליחה מהווטסאפ העסקי: כל קישור wa.me עם מספר נפתח כחלון עריכה, ונשלח דרך העוזרת במק (תור בשרת) */
function parseWa(u){ var m=String(u||'').match(/wa\.me\/(\d{8,15})(?:\?text=([^#]*))?/); if(!m) return null; var t=''; try{ t=decodeURIComponent((m[2]||'').replace(/\+/g,' ')); }catch(e){ t=m[2]||''; } return {phone:m[1], text:t}; }
function stripEmo(s){ return String(s||'').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}\u{20E3}]/gu,'').replace(/[ \t]{2,}/g,' ').trim(); }
function composeWa(url, name, after){ var p=parseWa(url); if(!p){ window.open(url,'_blank'); return; } var ov=document.createElement('div'); ov.className='ov';
  ov.innerHTML='<div class="sheet"><div class="sh"><h2>'+esc(name?'הודעה ל'+name:'הודעה ל-0'+p.phone.slice(3))+'</h2><button class="x" aria-label="סגירה">×</button></div><div class="s" style="font-size:13px;color:var(--mute);margin-bottom:6px">יוצא מהווטסאפ העסקי. אפשר לערוך לפני השליחה.</div><textarea id="cwT" rows="7" style="width:100%;font:inherit;font-size:16px;padding:10px;border:1px solid var(--line);border-radius:12px">'+esc(stripEmo(p.text))+'</textarea><button class="btn p big1" id="cwS">שליחה מהווטסאפ העסקי</button><a style="display:block;text-align:center;margin-top:12px;font-size:13px;color:var(--mute)" target="_blank" rel="noopener" id="cwO" href="'+esc(url)+'">לפתוח בווטסאפ במקום</a></div>';
  document.body.appendChild(ov); var close=function(){ ov.remove(); }; ov.querySelector('.x').onclick=close; ov.onclick=function(e){ if(e.target===ov) close(); };
  ov.querySelector('#cwO').onclick=function(){ close(); if(after) after(); };
  ov.querySelector('#cwS').onclick=function(){ var b=this, t=$('#cwT').value.trim(); if(!t){ toast('ההודעה ריקה'); return; } b.disabled=true; b.textContent='שולח…';
    google.script.run.withSuccessHandler(function(r){ close(); toast('בתור. יוצא מהעסקי תוך חצי דקה'); if(after) after(); waTrack(r.id, name||('0'+p.phone.slice(3))); }).withFailureHandler(function(e){ b.disabled=false; b.textContent='שליחה מהווטסאפ העסקי'; toast(e.message); }).dashboardWaSend(p.phone,t,name||''); }; }
function waTrack(id,who){ var n=0, tick=function(){ n++; google.script.run.withSuccessHandler(function(m){ var st=m&&m[id]; if(st==='נשלח') toast('נשלח ל'+who); else if(st&&st.indexOf('נכשל')===0) toast('לא נשלח ל'+who+': '+st.replace(/^נכשל:\s*/,'')); else if(n<15) setTimeout(tick,8000); else toast('ההודעה ל'+who+' עדיין בתור. העוזרת במק דולקת?'); }).withFailureHandler(function(){}).dashboardWaStatus([id]); }; setTimeout(tick,6000); }
document.addEventListener('click',function(e){ var a=e.target&&e.target.closest&&e.target.closest('a[href*="wa.me/"]'); if(!a||a.id==='cwO'||!parseWa(a.href)) return; e.preventDefault(); e.stopPropagation();
